/**
 * Money utility functions for converting between SDK Money types and MoneyData
 */
import type { MoneyData } from '@wix/headless-components/react';
/**
 * Converts SDK Money format to MoneyData format
 *
 * The original SDK value is validated as a whole (values that are not fully
 * numeric and finite, like `"12.34xyz"`, return `null`) but kept as-is, so
 * string amounts reach `Money` with full decimal precision instead of being
 * routed through floating point. Compare amounts numerically with
 * `Number(money.amount)`.
 *
 * @param sdkMoney - The SDK money object with value, currency, and optional formattedValue
 * @returns MoneyData object with amount and currency, or null if conversion fails
 *
 * @example
 * ```ts
 * const money = convertToMoneyData({ value: "25.50", currency: "USD" });
 * // Returns: { amount: "25.50", currency: "USD" }
 * ```
 */
export declare function convertToMoneyData(sdkMoney: {
    value?: string;
    currency?: string;
    formattedValue?: string | null;
} | undefined): MoneyData | null;
/**
 * Converts ecom MultiCurrencyPrice format to MoneyData format
 *
 * The string amount is validated as a whole (values that are not fully
 * numeric and finite, like `"12.34xyz"`, return `null`) but kept as-is, so
 * it reaches `Money` with full decimal precision. Compare amounts
 * numerically with `Number(money.amount)`.
 *
 * @param price - The MultiCurrencyPrice object with amount as string
 * @param currency - The currency code (from response level)
 * @returns MoneyData object or null if conversion fails
 */
export declare function convertMultiCurrencyPriceToMoneyData(price: {
    amount?: string;
} | undefined, currency: string): MoneyData | null;
